let number = 0;
export const b1t7QuestionBank = groups.flatMap(([section, rows]) => rows.map(([prompt, labels, reason, reference]) => {
  const offset = number++ % 4;
  const rotated = [...labels.slice(offset), ...labels.slice(0, offset)];
  return {
    id: `b1t7-practice-${String(number).padStart(3, "0")}`,
    section, prompt,
    options: rotated.map((label, index) => ({ id: "abcd"[index], label })),
    correctOption: "abcd"[(4 - offset) % 4],
    explanation: `${reason} Referencia del temario: B1T7 · ${reference}.`,
  };
}));
